ALTER TABLE reviews ADD COLUMN image_url VARCHAR(120);
CREATE TABLE bookmarks (user_id UUID NOT NULL REFERENCES users(id), post_id UUID NOT NULL REFERENCES posts(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY (user_id, post_id));
CREATE TABLE comments (id UUID PRIMARY KEY, post_id UUID NOT NULL REFERENCES posts(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id), author_name VARCHAR(120) NOT NULL,
  body VARCHAR(1000) NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
